-- The three Pakangers Open starter templates.
--
-- Scoring for every official event: brackets, Round of 16 and quarterfinals
-- to 11 sudden death; semifinals and third place to 15 sudden death;
-- championship to 15 win by 2, capped at 21.

update public.tournament_template set name = 'Pakangers Open — 2 Brackets to Quarter Finals'
where name = 'Pakangers — 2 Brackets to Quarter Finals';

with v(name, description, config) as (
  values ('Pakangers Open — 2 Brackets to Quarter Finals', 'Two brackets of up to 8 teams, round robin to 11 sudden death. Top 4 of each bracket cross over into the quarterfinals (A1 vs B4, A2 vs B3, A3 vs B2, A4 vs B1) to 11 sudden death. Semifinals and third place to 15 sudden death; championship to 15 win by 2, capped at 21.', '{"divisions":[{"key":"open_doubles","name":"Open Doubles","teamSize":2}],"stages":[{"key":"pools","name":"Bracket","formatKey":"round_robin","sequence":1,"scoring":{"pointsToWin":11,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":["match_wins","head_to_head_two_way","point_differential","points_scored","coin_flip"],"groups":[{"name":"A","size":8},{"name":"B","size":8}]},{"key":"quarterfinals","name":"Quarterfinals","formatKey":"single_elimination","sequence":2,"scoring":{"pointsToWin":11,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"group_rank","group":"A","rank":1},"away":{"kind":"group_rank","group":"B","rank":4}},{"match":2,"home":{"kind":"group_rank","group":"A","rank":3},"away":{"kind":"group_rank","group":"B","rank":2}},{"match":3,"home":{"kind":"group_rank","group":"B","rank":1},"away":{"kind":"group_rank","group":"A","rank":4}},{"match":4,"home":{"kind":"group_rank","group":"B","rank":3},"away":{"kind":"group_rank","group":"A","rank":2}}]},{"key":"semifinals","name":"Semifinals","formatKey":"single_elimination","sequence":3,"scoring":{"pointsToWin":15,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"quarterfinals","match":1,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"quarterfinals","match":2,"outcome":"winner"}},{"match":2,"home":{"kind":"match_outcome","stage":"quarterfinals","match":3,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"quarterfinals","match":4,"outcome":"winner"}}]},{"key":"third_place","name":"3rd Place","formatKey":"single_elimination","sequence":4,"scoring":{"pointsToWin":15,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"semifinals","match":1,"outcome":"loser"},"away":{"kind":"match_outcome","stage":"semifinals","match":2,"outcome":"loser"}}]},{"key":"championship","name":"Championship","formatKey":"single_elimination","sequence":5,"scoring":{"pointsToWin":15,"winBy":"win_by_two","bestOf":1,"scoringType":"side_out","cap":21},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"semifinals","match":1,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"semifinals","match":2,"outcome":"winner"}}]}],"qualification":[{"fromStage":"pools","fromGroup":"A","method":"top_n","value":4,"toStage":"quarterfinals"},{"fromStage":"pools","fromGroup":"B","method":"top_n","value":4,"toStage":"quarterfinals"}]}'::jsonb)
), updated as (
  update public.tournament_template t
  set description = v.description, config = v.config
  from v where t.name = v.name
  returning t.id
)
insert into public.tournament_template (name, description, config)
select name, description, config from v
where not exists (select 1 from updated);

