  values ('Pakangers Open — 4 Brackets to Quarter Finals', 'Four brackets, round robin to 11 sudden death. Top 2 of each bracket cross over into the quarterfinals (A1 vs D2, B1 vs C2, C1 vs B2, D1 vs A2) to 11 sudden death. Semifinals and third place to 15 sudden death; championship to 15 win by 2, capped at 21.', '{"divisions":[{"key":"open_doubles","name":"Open Doubles","teamSize":2}],"stages":[{"key":"pools","name":"Bracket","formatKey":"round_robin","sequence":1,"scoring":{"pointsToWin":11,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":["match_wins","head_to_head_two_way","point_differential","points_scored","coin_flip"],"groups":[{"name":"A","size":4},{"name":"B","size":4},{"name":"C","size":4},{"name":"D","size":4}]},{"key":"quarterfinals","name":"Quarterfinals","formatKey":"single_elimination","sequence":2,"scoring":{"pointsToWin":11,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"group_rank","group":"A","rank":1},"away":{"kind":"group_rank","group":"D","rank":2}},{"match":2,"home":{"kind":"group_rank","group":"B","rank":1},"away":{"kind":"group_rank","group":"C","rank":2}},{"match":3,"home":{"kind":"group_rank","group":"C","rank":1},"away":{"kind":"group_rank","group":"B","rank":2}},{"match":4,"home":{"kind":"group_rank","group":"D","rank":1},"away":{"kind":"group_rank","group":"A","rank":2}}]},{"key":"semifinals","name":"Semifinals","formatKey":"single_elimination","sequence":3,"scoring":{"pointsToWin":15,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"quarterfinals","match":1,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"quarterfinals","match":2,"outcome":"winner"}},{"match":2,"home":{"kind":"match_outcome","stage":"quarterfinals","match":3,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"quarterfinals","match":4,"outcome":"winner"}}]},{"key":"third_place","name":"3rd Place","formatKey":"single_elimination","sequence":4,"scoring":{"pointsToWin":15,"winBy":"sudden_death","bestOf":1,"scoringType":"side_out"},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"semifinals","match":1,"outcome":"loser"},"away":{"kind":"match_outcome","stage":"semifinals","match":2,"outcome":"loser"}}]},{"key":"championship","name":"Championship","formatKey":"single_elimination","sequence":5,"scoring":{"pointsToWin":15,"winBy":"win_by_two","bestOf":1,"scoringType":"side_out","cap":21},"tiebreakers":[],"entrants":[{"match":1,"home":{"kind":"match_outcome","stage":"semifinals","match":1,"outcome":"winner"},"away":{"kind":"match_outcome","stage":"semifinals","match":2,"outcome":"winner"}}]}],"qualification":[{"fromStage":"pools","fromGroup":"A","method":"top_n","value":2,"toStage":"quarterfinals"},{"fromStage":"pools","fromGroup":"B","method":"top_n","value":2,"toStage":"quarterfinals"},{"fromStage":"pools","fromGroup":"C","method":"top_n","value":2,"toStage":"quarterfinals"},{"fromStage":"pools","fromGroup":"D","method":"top_n","value":2,"toStage":"quarterfinals"}]}'::jsonb)
), updated as (
  update public.tournament_template t
  set description = v.description, config = v.config
  from v where t.name = v.name
  returning t.id
